path.d:
M $cap 0
        a $cap {{$height / 2}} 0 0 0 0 $height
        a $cap {{$height / 2}} 0 0 0 0 {{-$height}}
        h {{$width - 2 * $cap}}
        a $cap {{$height / 2}} 0 0 1 0 $height
        h {{-($width - 2 * $cap)}}

M 0 $mid_y
        a $ring $ring 0 1 0 {{2 * $ring}} 0
        a $ring $ring 0 1 0 {{-2 * $ring}} 0
        M {{$ring - $inner}} $mid_y
        a $inner $inner 0 1 0 {{2 * $inner}} 0
        a $inner $inner 0 1 0 {{-2 * $inner}} 0
        M {{2 * $ring}} $mid_y H {{$width * 0.76}}
        V {{$height * 0.34}} H {{$width * 0.88}} V $mid_y
        H $width V {{$height * 0.68}}
        H {{$width * 0.88}} V {{$height * 0.56}}
        H {{$width * 0.68}} V {{$height * 0.76}}
        H {{$width * 0.56}}

M $shackle $top V {{$height * 0.22}}
        Q $shackle 0 $mid_x 0
        Q {{$width - $shackle}} 0 {{$width - $shackle}} {{$height * 0.22}}
        V $top
        M 0 $top H $width V $height H 0 Z
        M {{$mid_x - $key_r}} {{$height * 0.62}}
        a $key_r $key_r 0 1 0 {{2 * $key_r}} 0
        a $key_r $key_r 0 1 0 {{-2 * $key_r}} 0
        M $mid_x {{$height * 0.73}} V {{$height * 0.88}}

M 0 0 H $tab_x V $tab_h H {{$tab_x + $tab_w}} V 0 H $width V $height H 0 Z
        M $line_l {{$height * 0.34}} H {{$width * 0.84}}
        M $line_l {{$height * 0.54}} H {{$width * 0.74}}
        M $line_l {{$height * 0.74}} H {{$width * 0.8}}

M $left $height V {{$height * 0.16}} H $step V 0 H $right V $height Z
        M {{$width * 0.38}} {{$height * 0.24}} H {{$width * 0.62}}
        M {{$width * 0.38}} {{$height * 0.42}} H {{$width * 0.62}}
        M {{$width * 0.38}} {{$height * 0.6}} H {{$width * 0.62}}
        M {{$width * 0.38}} {{$height * 0.78}} H {{$width * 0.62}}

M 0 0 H $width V $height H 0 Z
        M 0 $row1 H $width
        M 0 $row2 H $width
        M {{$width * 0.16}} {{$row1 / 2}} H {{$width * 0.72}}
        M {{$width * 0.16}} {{$height / 2}} H {{$width * 0.72}}
        M {{$width * 0.16}} {{$height * 5 / 6}} H {{$width * 0.72}}
        M {{$width * 0.84}} {{$row1 / 2}}
        a $light $light 0 1 0 {{2 * $light}} 0
        a $light $light 0 1 0 {{-2 * $light}} 0
        M {{$width * 0.84}} {{$height / 2}}
        a $light $light 0 1 0 {{2 * $light}} 0
        a $light $light 0 1 0 {{-2 * $light}} 0
        M {{$width * 0.84}} {{$height * 5 / 6}}
        a $light $light 0 1 0 {{2 * $light}} 0
        a $light $light 0 1 0 {{-2 * $light}} 0

M 0 0 H $width V $screen H 0 Z
        M $mid_x $screen V $base
        M {{$width * 0.24}} $height H {{$width * 0.76}}

M 0 0 H $width V $height H 0 Z
        M 0 $bar H $width
        M {{$width * 0.18}} {{$height * 0.34}} L {{$width * 0.34}} $mid L {{$width * 0.18}} {{$height * 0.66}}
        M {{$width * 0.44}} {{$height * 0.66}} H {{$width * 0.78}}

M {{$mid_x - $ring}} $mid_y
        a $ring $ring 0 1 0 {{2 * $ring}} 0
        a $ring $ring 0 1 0 {{-2 * $ring}} 0
        M {{$width * 0.22}} $mid_y H {{$width * 0.78}}
        M {{$width * 0.3}} {{$mid_y - $head}} L {{$width * 0.22}} $mid_y L {{$width * 0.3}} {{$mid_y + $head}}
        M {{$width * 0.7}} {{$mid_y - $head}} L {{$width * 0.78}} $mid_y L {{$width * 0.7}} {{$mid_y + $head}}
        M $mid_x {{$height * 0.22}} V {{$height * 0.78}}
        M {{$mid_x - $head}} {{$height * 0.3}} L $mid_x {{$height * 0.22}} L {{$mid_x + $head}} {{$height * 0.3}}
        M {{$mid_x - $head}} {{$height * 0.7}} L $mid_x {{$height * 0.78}} L {{$mid_x + $head}} {{$height * 0.7}}
